
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_ghds10_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_ghds10", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([1.174841431509759e+02, 1.137782488883778e+02, 1.087061547160666e+02, 1.019131871078543e+02, 9.309347079881374e+01, 8.213719569010793e+01, 6.934874371423216e+01, 5.564767101570505e+01, 4.246017756377439e+01, 3.053417839824282e+01, 1.669963425197150e+01, 4.469852462890752e+00, 3.084213297560540e+00, 2.584054706844269e+00, 1.916097347889853e+00, 1.270364137386604e+00, 6.898561242414096e-01, 6.242921729552426e-02, -7.354776553677671e-01, -1.830186901528192e+00]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


